## Task

Refactor the `useAuth` hook to support token refresh and add unit tests.

## Constraints

- Do not change the public API of `useAuth`
- Keep the refresh logic in a separate composable
- Tests must cover the 401 → refresh → retry flow

## Selected Files

### `src/hooks/useAuth.ts` (lines 1–42)

```ts
import { useState, useCallback, useEffect } from 'react';
import { apiClient } from '@/lib/api';

interface AuthState {
  user: User | null;
  token: string | null;
  isAuthenticated: boolean;
}

export function useAuth() {
  const [state, setState] = useState<AuthState>({
    user: null,
    token: localStorage.getItem('token'),
    isAuthenticated: false,
  });

  const login = useCallback(async (email: string, password: string) => {
    const res = await apiClient.post('/auth/login', { email, password });
    const { token, user } = res.data;
    localStorage.setItem('token', token);
    setState({ user, token, isAuthenticated: true });
  }, []);

  const logout = useCallback(() => {
    localStorage.removeItem('token');
    setState({ user: null, token: null, isAuthenticated: false });
  }, []);

  useEffect(() => {
    if (state.token) {
      apiClient.get('/auth/me').then(res => {
        setState(s => ({ ...s, user: res.data, isAuthenticated: true }));
      }).catch(() => logout());
    }
  }, [state.token]);

  return { ...state, login, logout };
}
```

### `src/lib/api.ts` (lines 1–18)

